fn read_fields(database: &SqliteDatabase, name: &str, byte_name: &str, parents: &BTreeSet<i64>, control: &mut SqliteSnapshotControl<'_>) -> Result<BTreeMap<i64, Vec<ZipExtraField>>,ValueError> {
